        "inclusion": {"scale_min": 0.60, "scale_max": 1.40, "target_pool": "same_class", "source_weighting": "uniform", "max_overlap": 0.15, "sources": []},
        "patches": {"scale_min": 0.60, "scale_max": 1.40, "target_pool": "same_class", "source_weighting": "uniform", "max_overlap": 0.15, "sources": []},
